/**
 * Rename and/or activate a worksheet. Never touches cell data.
 *
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @param {{ name?: unknown, isActive?: unknown }} patch
 * @returns {{ worksheet: WorksheetSnapshot, updatedAt: string }}
 */
export function patchWorksheet(db, ws, patch) {
  /** @type {{ name?: string, isActive?: boolean }} */
  const fields = {};

  if (patch.name !== undefined) {
    if (typeof patch.name !== 'string') throw invalidBody('Worksheet name must be a string');
    const name = patch.name.trim();
    if (!name) throw validationError('Worksheet name cannot be empty');
    assertWorksheetNameAvailable(db, ws.workbook_id, ws.id, name);
    fields.name = name;
  }
  if (patch.isActive !== undefined) {
    if (typeof patch.isActive !== 'boolean') throw invalidBody('isActive must be a boolean');
    fields.isActive = patch.isActive;
  }
  if (fields.name === undefined && fields.isActive === undefined) {
    throw invalidBody('Nothing to update');
  }

  const at = nowIso();
  db.transaction(() => {
    if (fields.name !== undefined) {
      db.prepare('UPDATE worksheets SET name = ? WHERE id = ?').run(fields.name, ws.id);
    }
    if (fields.isActive !== undefined) {
      db.prepare('UPDATE worksheets SET last_active = 0 WHERE workbook_id = ?').run(ws.workbook_id);
      db.prepare('UPDATE worksheets SET last_active = ? WHERE id = ?').run(
        fields.isActive ? 1 : 0,
        ws.id,
      );
    }
    // Renaming is a visible workbook change; activating a tab is pure view
    // state and must not change "Last updated" (see PR #2 notes).
    if (fields.name !== undefined) touchWorkbook(db, ws.workbook_id, at);
  })();

  const updated = getWorksheetRow(db, ws.id);
  if (!updated) throw notFound('Worksheet not found');
  const workbook = getWorkbookRow(db, ws.workbook_id);
  return {
    worksheet: getWorksheetSnapshot(db, updated),
    updatedAt: fields.name !== undefined ? at : (workbook?.updated_at ?? at),
  };
}

